script:
frappe.ui.form.on('Contact', {
    refresh: function(frm) {
        if (!frm.doc.__islocal) {
            if (frm.doc.email_ids && frm.doc.email_ids.length > 0) {
                frm.emailIdsOnLoad = frm.doc.email_ids.map(row => JSON.stringify(row));
            }
        }
    },
    before_save: function(frm) {
        if (!frm.doc.__islocal) {
            if (frm.doc.email_ids && frm.doc.email_ids.length > 0) {
                frm.emailIdsOnLoad = frm.doc.email_ids.map(row => JSON.stringify(row));
                checkForDuplicates(frm);
            }
        }
    },
    before_save: function(frm) {
        if (frm.doc.email_ids && frm.doc.email_ids.length > 0) {
            var currentEmailIds = frm.doc.email_ids.map(row => JSON.stringify(row));

            if (frm.emailIdsOnLoad && JSON.stringify(frm.emailIdsOnLoad) !== JSON.stringify(currentEmailIds)) {
                checkForDuplicates(frm);
            }
        }
    }
});


function checkForDuplicates(frm) {
    console.log('Проверка дублей по email');
    var primaryEmailIds = frm.doc.email_ids.filter(function(row) {
        return row.is_primary;
    }).map(function(row) {
        return row.email_id;
    });

    if (frm.doc.email_id && primaryEmailIds.includes(frm.doc.email_id)) {
        primaryEmailIds.push(frm.doc.email_id);
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Contact',
            filters: {
                email_id: ['in', primaryEmailIds]
            },
            fields: ['email_id', 'name'] // Добавлено поле name
        },
        callback: function(response) {
            if (response.message && response.message.length > 0) {
                var duplicates = response.message.filter(function(contact) {
                    return primaryEmailIds.includes(contact.email_id);
                });

                if (duplicates.length > 0) {
                    var messageParts = duplicates.map(function(contact) {
                        return '<a href="/app/contact/' + contact.name + '">' + contact.name + '</a> (электронный адрес: ' + contact.email_id + ')';
                    });

                    var message = __('Подтвердите создание дубля. Уже существуют данные: ') + messageParts.join(', ');
                    
                     frappe.confirm( message,
                        () => {
                            // action to perform if Yes is selected
                            frm.save();
                        }, () => {
                            // action to perform if No is selected
                        });
                } else {
                    frm.save();
                }
            }
        }
    });
}

frappe.ui.form.on('Event', {
    event_type: function(frm) {
        if (frm.doc.event_type == 'Public') {
            frappe.confirm(__('Вы уверены, что хотите сохранить событие как общее? Общие события отображаются для всех пользователей системы.'),
                () => {
                    // action to perform if Yes is selected
                }, () => {
                    // action to perform if No is selected
                    frm.set_value('event_type', 'Private');
                });
        }
    }
})
